mapper.select:
SELECT COUNT(*)
FROM refund_record
WHERE order_id = #{orderId}

mapper.update:
UPDATE ticket_order
SET order_status = 'REFUNDING',
    update_time = #{now}
WHERE order_id = #{orderId}
  AND order_status = 'WAIT_USE'

UPDATE refund_record
SET refund_status = 'REFUND_SUCCESS',
    refund_time = #{refundTime},
    update_time = #{refundTime}
WHERE refund_id = #{refundId}
  AND refund_status = 'REFUNDING'

UPDATE ticket_order
SET order_status = 'REFUND_SUCCESS',
    update_time = #{now}
WHERE order_id = #{orderId}
  AND order_status = 'REFUNDING'
